/**
 * @method
 * @name polymarket#fetchMarkets
 * @description retrieves data on all markets for polymarket, each prediction market becomes one market with its outcome tokens listed under the outcomes key
 * @see https://docs.polymarket.com/api-reference/events/list-events
 * @see https://docs.polymarket.com/api-reference/search/search-markets-events-and-profiles
 * @param {object} [params] extra exchange-specific parameters
 * @param {string} [params.query] a single search term used to filter the fetched events
 * @param {string[]} [params.queries] multiple search terms (alternative to query)
 * @param {string[]} [params.tags] filter events by tag — human-readable labels ("Fed Rates") or slugs ("fed-rates") both work; multiple tags match ANY (one gamma listing per tag, unioned)
 * @param {string} [params.status] 'active', 'closed' or 'all', the status of the events to fetch, defaults to 'active'
 * @param {int} [params.limit] max number of events to fetch when no query is given (defaults to options.fetchMarketsLimit, 200); the listing is ordered by 24h volume so the most active markets come first — outcomes on lower-volume markets are resolvable on demand by their token id (fetchOutcome)
 * @returns {object[]} an array of objects representing market data
 */
func (this *Polymarket) FetchMarketsAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[[]ccxt.MarketInterface] {
	ch := make(chan ccxt.AsyncResult[[]ccxt.MarketInterface], 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchMarketsBody(ch chan ccxt.AsyncResult[[]ccxt.MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var queries []any = this.ParseSearchQueries(params)
	var rest map[string]any = this.OmitDict(params, []any{"query", "queries"})
	var queriesLength int = len(queries)
	var rawEvents any = []any{}
	if queriesLength > 0 {

		r := <-this.FetchRawEventsBySearchAsync(queries, rest)
		if r.Err != nil {
			panic(r.Err)
		}
		if r.Value == nil {
			rawEvents = nil
		} else {
			rawEvents = ccxt.MapSliceToList(r.Value)
		}
	} else {

		r1 := <-this.FetchRawEventsListAsync(rest)
		if r1.Err != nil {
			panic(r1.Err)
		}
		if r1.Value == nil {
			rawEvents = nil
		} else {
			rawEvents = ccxt.MapSliceToList(r1.Value)
		}
	}
	var flatMarkets []any = []any{}
	var eventsDict map[string]any = map[string]any{}
	for rei := 0; rei < ccxt.GetArrayLength(rawEvents); rei++ {
		var rawEvent any = ccxt.GetValue(rawEvents, rei)
		var ccxtMarkets []any = ccxt.ArrayTyped(this.ParseEventToMarkets(rawEvent))
		for mi := 0; mi < len(ccxtMarkets); mi++ {
			flatMarkets = append(flatMarkets, ccxt.DerefScalar(ccxtMarkets[mi]))
		}
		var parsedEvent map[string]any = this.ParseEvent(rawEvent)
		var eventSlug *string = this.SafeString(rawEvent, "slug")
		if (eventSlug != nil) && (eventSlug == nil || *eventSlug != "") {
			var eventKey any = this.ShortenSlug(eventSlug)
			ccxt.AddElementToObject(eventsDict, eventKey, parsedEvent)
		}
	}
	this.Events = eventsDict

	ch <- ccxt.AsyncResult[[]ccxt.MarketInterface]{Value: ccxt.MarketInterfacesFromList(flatMarkets)}
	return nil
}

/**
 * @ignore
 * @method
 * @name polymarket#fetchRawEventsBySearch
 * @description fetches raw gamma event objects matching the given search terms, paginating through all result pages
 * @see https://docs.polymarket.com/api-reference/search/search-markets-events-and-profiles
 * @param {string[]} queries search terms
 * @param {object} [params] extra exchange-specific parameters
 * @param {int} [params.limit] page size per search query, defaults to 50
 * @returns {object[]} an array of raw gamma event objects
 */
func (this *Polymarket) FetchRawEventsBySearchAsync(queries any, optionalArgs ...any) <-chan ccxt.AsyncResult[[]map[string]any] {
	ch := make(chan ccxt.AsyncResult[[]map[string]any], 1)
	go this.fetchRawEventsBySearchBody(ch, queries, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchRawEventsBySearchBody(ch chan ccxt.AsyncResult[[]map[string]any], queries any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var resultLimit *int64 = this.SafeInteger(params, "limit")
	// fixed page size (gamma's limit_per_type). do NOT tie it to `limit`: that made a small
	// limit fan out into many tiny-page requests (limit:1 -> ~one request per matching event).
	// tunable per-call via params.searchPageSize, else the exchange option, else 100
	var optionPageSize *int64 = this.SafeInteger(this.Options, "searchPageSize", 100)
	var pageSize *int64 = this.SafeInteger(params, "searchPageSize", optionPageSize)
	// map the unified sort/status onto the gamma search params
	var sort *string = this.SafeString(params, "sort")
	var sortParam string = "volume"
	if sort != nil && *sort == "liquidity" {
		sortParam = "liquidity"
	} else if sort != nil && *sort == "newest" {
		sortParam = "startDate"
	}
	var status *string = this.SafeString(params, "status", "active")
	var eventsStatus any = "active"
	if (status != nil && *status == "closed") || (status != nil && *status == "inactive") {
		eventsStatus = "closed"
	} else if status != nil && *status == "all" {
		eventsStatus = nil
	}
	var rest map[string]any = this.OmitDict(params, []any{"limit", "sort", "status", "searchIn", "eventId", "slug", "query", "queries", "searchPageSize", "maxSearchPages"})
	var seen map[string]any = map[string]any{}
	var rawEvents []any = []any{}
	for qi := 0; qi < ccxt.GetArrayLength(queries); qi++ {
		var q *string = ccxt.SafeStringPtr(ccxt.GetValue(queries, qi))
		var baseRequest map[string]any = map[string]any{
			"q":              q,
			"limit_per_type": pageSize,
			"sort":           sortParam,
			"ascending":      false,
		}
		if eventsStatus != nil {
			baseRequest["events_status"] = eventsStatus
		}
		var firstRequest map[string]any = map[string]any{
			"page": 1,
		}
		firstRequest = this.Extend(this.Extend(firstRequest, baseRequest), rest)

		r := <-this.GammaPublicGetPublicSearch(firstRequest)
		if r.Err != nil {
			panic(r.Err)
		}
		var first map[string]any = r.Value
		var firstEvents []any = ccxt.SafeListTyped(first, "events")
		var firstEventsLength int = len(firstEvents)
		var pagination map[string]any = ccxt.SafeMapTyped(first, "pagination")
		var totalResults *int64 = this.SafeInteger(pagination, "totalResults", firstEventsLength)
		var totalPages any = this.ParseToInt(math.Ceil(float64(*totalResults) / float64(*pageSize)))
		// only page as far as `limit` needs (applyEventFetchParams slices to it afterwards)
		// with no limit, cap the fan-out at options.maxSearchPages so a broad query stays bounded
		if resultLimit != nil {
			var limitPages int64 = this.ParseToInt(math.Ceil(float64(*resultLimit) / float64(*pageSize)))
			if ccxt.IsLessThan(limitPages, totalPages) {
				totalPages = limitPages
			}
		} else {
			var optionMaxPages *int64 = this.SafeInteger(this.Options, "maxSearchPages", 5)
			var maxSearchPages *int64 = this.SafeInteger(params, "maxSearchPages", optionMaxPages)
			if ccxt.IsLessThan(maxSearchPages, totalPages) {
				totalPages = maxSearchPages
			}
		}
		var remainingPages []any = []any{}
		for p := 2; ccxt.IsLessThanOrEqual(p, totalPages); p++ {
			remainingPages = append(remainingPages, p)
		}
		var restPromises []any = []any{}
		for pi := 0; pi < len(remainingPages); pi++ {
			var pageRequest map[string]any = map[string]any{
				"page": ccxt.DerefScalar(remainingPages[pi]),
			}
			pageRequest = this.Extend(this.Extend(pageRequest, baseRequest), rest)
			restPromises = append(restPromises, this.GammaPublicGetPublicSearch(pageRequest))
		}

		r1 := <-ccxt.PromiseAll(restPromises)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var restResponses []any = ccxt.ListTyped(r1.Value)
		var allEvents []any = []any{}
		for fi := 0; fi < len(firstEvents); fi++ {
			allEvents = append(allEvents, firstEvents[fi])
		}
		for ri := 0; ri < len(restResponses); ri++ {
			var pageEvents []any = ccxt.SafeListTyped(restResponses[ri], "events")
			for ei := 0; ei < len(pageEvents); ei++ {
				allEvents = append(allEvents, pageEvents[ei])
			}
		}
		for ei := 0; ei < len(allEvents); ei++ {
			var rawEvent any = allEvents[ei]
			var eventId *string = this.SafeString(rawEvent, "id")
			if ((eventId != nil) && (eventId == nil || *eventId != "")) && !(func() bool {
				if eventId == nil {
					return false
				}
				_, ok := seen[*eventId]
				return ok
			}()) {
				if eventId != nil {
					seen[*eventId] = true
				}
				rawEvents = append(rawEvents, rawEvent)
			}
		}
	}

	ch <- ccxt.AsyncResult[[]map[string]any]{Value: ccxt.MapSliceFromList(rawEvents)}
	return nil
}

/**
 * @ignore
 * @method
 * @name polymarket#tagToSlug
 * @description converts a human-readable tag label into gamma's slug form, "Fed Rates" -> "fed-rates"; lowercase alphanumeric runs joined by single dashes, so a tag already in slug form passes through unchanged
 * @param {string} tag the tag label or slug
 * @returns {string} the gamma tag slug
 */
func (this *Polymarket) TagToSlug(tag *string) string {
	var lower string = strings.ToLower(*tag)
	var allowed string = "abcdefghijklmnopqrstuvwxyz0123456789"
	var chars []string = this.StringToCharsArray(lower)
	var slug string = ""
	var pendingSep bool = false
	for i := 0; i < len(chars); i++ {
		var ch string = chars[i]
		if strings.Index(allowed, ch) >= 0 {
			if pendingSep && (slug != "") {
				slug = slug + "-"
			}
			slug = slug + ch
			pendingSep = false
		} else {
			pendingSep = true
		}
	}
	if slug == "" {
		// a tag with no alphanumerics at all — pass it through so gamma just returns no match
		return lower
	}
	return slug
}

/**
 * @ignore
 * @method
 * @name polymarket#fetchRawEventsList
 * @description fetches raw gamma event objects from the events listing endpoint, paginating in parallel
 * @see https://docs.polymarket.com/api-reference/events/list-events
 * @param {object} [params] extra exchange-specific parameters
 * @param {string} [params.status] 'active', 'closed' or 'all', defaults to options.defaultEventStatus
 * @param {int} [params.limit] max number of events to fetch (default options.fetchMarketsLimit); the listing is ordered by 24h volume so the most active markets come first
 * @returns {object[]} an array of raw gamma event objects
 */
func (this *Polymarket) FetchRawEventsListAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[[]map[string]any] {
	ch := make(chan ccxt.AsyncResult[[]map[string]any], 1)
	go this.fetchRawEventsListBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchRawEventsListBody(ch chan ccxt.AsyncResult[[]map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// gamma hard-caps each response at 100 events regardless of the requested limit, so the
	// page size must be that cap or pagination never advances (the > check below stays false)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var pageSize *int64 = this.SafeInteger(this.Options, "eventsPageSize", 100)
	// scope the listing: without a search query loadMarkets would otherwise dump every
	// active event (tens of thousands of markets). Cap to `limit` events (most-traded first).
	var limit *int64 = this.SafeInteger(params, "limit", this.SafeInteger(this.Options, "fetchMarketsLimit", 200))
	var maxPages float64 = math.Ceil(float64(*limit) / float64(*pageSize))
	var status *string = this.SafeString(params, "status", this.SafeString(this.Options, "defaultEventStatus", "active"))
	// sort maps to the gamma `order` field; 'volume' is the default ranking
	var sort *string = this.SafeString(params, "sort")
	var order string = "volume"
	if sort != nil && *sort == "liquidity" {
		order = "liquidity"
	} else if sort != nil && *sort == "newest" {
		order = "startDate"
	}
	var rest map[string]any = this.OmitDict(params, []any{"status", "limit", "sort", "searchIn", "eventId", "slug", "query", "queries", "tags"})
	var baseRequest map[string]any = map[string]any{
		"limit":     pageSize,
		"order":     order,
		"ascending": false,
	}
	baseRequest = this.Extend(baseRequest, rest)
	// push requested tags server-side (gamma accepts one tag_slug per request) so a tags-only
	// fetchEvents returns the tagged events rather than filtering the top-volume listing down
	// to nothing; multiple tags run one listing per tag, unioned and deduped by event id
	var requestedTags []any = ccxt.SafeListTyped(params, "tags")
	var requestedTagsLength int = len(requestedTags)
	if requestedTagsLength > 1 {
		var seen map[string]any = map[string]any{}
		var unioned []any = []any{}
		for ti := 0; ti < requestedTagsLength; ti++ {
			var singleTagParams map[string]any = this.Extend(map[string]any{}, params)
			singleTagParams["tags"] = []any{requestedTags[ti]}

			r := <-this.FetchRawEventsListAsync(singleTagParams)
			if r.Err != nil {
				panic(r.Err)
			}
			var tagEvents []any = ccxt.MapSliceToList(r.Value)
			for ei := 0; ei < len(tagEvents); ei++ {
				var rawEvent any = tagEvents[ei]
				var eventId *string = this.SafeString(rawEvent, "id")
				if eventId != nil {
					if _, ok := seen[*eventId]; !ok {
						seen[*eventId] = true
						unioned = append(unioned, rawEvent)
					}
				}
			}
		}

		ch <- ccxt.AsyncResult[[]map[string]any]{Value: ccxt.MapSliceFromList(unioned)}
		return nil
	}
	if requestedTagsLength > 0 {
		// gamma matches tag_slug case-insensitively but only in slug form ("fed-rates"),
		// so human-readable labels ("Fed Rates") must be slugified first
		baseRequest["tag_slug"] = this.TagToSlug(this.SafeString(requestedTags, 0))
	}
	if status != nil && *status == "active" {
		baseRequest["active"] = true
		baseRequest["closed"] = false
	} else if (status != nil && *status == "closed") || (status != nil && *status == "inactive") {
		baseRequest["active"] = false
		baseRequest["closed"] = true
	}
	// 'all' — no active/closed filter
	// fetch page 1 first; if full, fire remaining pages in parallel
	var firstPageRequest map[string]any = map[string]any{
		"offset": 0,
	}
	firstPageRequest = this.Extend(firstPageRequest, baseRequest)

	r1 := <-this.GammaPublicGetEvents(firstPageRequest)
	if r1.Err != nil {
		panic(r1.Err)
	}
	firstPageResponse := r1.Raw
	var firstPageIsArray bool = ccxt.IsArray(firstPageResponse)
	var firstPage any = func() any {
		if firstPageIsArray {
			return firstPageResponse
		}
		return []any{}
	}()
	var firstPageLength int = ccxt.GetArrayLength(firstPage)
	var allRawEvents []any = []any{}
	for fi := 0; fi < firstPageLength; fi++ {
		allRawEvents = append(allRawEvents, ccxt.GetValue(firstPage, fi))
	}
	if pageSize == nil || int64(firstPageLength) >= *pageSize {
		var offsets []any = []any{}
		for p := 1; maxPages > float64(p); p++ {
			offsets = append(offsets, ccxt.Multiply(p, pageSize))
		}
		var restPromises []any = []any{}
		for oi := 0; oi < len(offsets); oi++ {
			var pageRequest map[string]any = map[string]any{
				"offset": ccxt.DerefScalar(offsets[oi]),
			}
			pageRequest = this.Extend(pageRequest, baseRequest)
			restPromises = append(restPromises, this.GammaPublicGetEvents(pageRequest))
		}

		r2 := <-ccxt.PromiseAll(restPromises)
		if r2.Err != nil {
			panic(r2.Err)
		}
		var restPages []any = ccxt.ListTyped(r2.Value)
		for ri := 0; ri < len(restPages); ri++ {
			var page []any = ccxt.SafeListTyped(restPages, ri)
			var pageLength int = len(page)
			for pi := 0; pi < pageLength; pi++ {
				allRawEvents = append(allRawEvents, page[pi])
			}
		}
	}
	var allRawEventsLength int = len(allRawEvents)
	if limit == nil || int64(allRawEventsLength) > *limit {

		ch <- ccxt.AsyncResult[[]map[string]any]{Value: ccxt.MapSliceFromList(this.ArraySlice(allRawEvents, 0, limit))}
		return nil
	}

	ch <- ccxt.AsyncResult[[]map[string]any]{Value: ccxt.MapSliceFromList(allRawEvents)}
	return nil
}
func (this *Polymarket) ParseEventToMarkets(event any) any {
	var eventSlug *string = this.SafeString(event, "slug", this.SafeString(event, "id"))
	var rawMarkets []any = ccxt.SafeListTyped(event, "markets")
	var result []any = []any{}
	//
	// {
	//    "id":"604489",
	//    "question":"Will Trump visit China by October 31?",
	//    "conditionId":"0x3d69cc559693ee46ba58da16e43c4e75b8da67b99c2e9a9d2f72bb0222d0f137",
	//    "slug":"will-trump-visit-china-by-october-31",
	//    "resolutionSource":"",
	//    "endDate":"2025-10-31T00:00:00Z",
	//    "startDate":"2025-09-19T21:22:54.912576Z",
	//    "image":"https://polymarket-upload.s3.us-east-2.amazonaws.com/will-trump-visit-china-by-october-31-ujqWMja0Uizt.png",
	//    "icon":"https://polymarket-upload.s3.us-east-2.amazonaws.com/will-trump-visit-china-by-october-31-ujqWMja0Uizt.png",
	//    "description":"If U.S. President Donald Trump visits China by October 31, 2025, 11:59 PM ET, this market will resolve to \\""Yes\\"". Otherwise, this market will resolve to \\""No\\"".\\n\\nFor the purpose of this market, a \\""visit\\"" is defined as Trump physically entering the terrestrial or maritime territory of the listed country. Whether or not Trump enters the country's airspace during the timeframe of this market will have no bearing on a positive resolution.\\n\\nThe primary resolution source for this information will be official information from government of the United States of America, official information from Trump or released by his verified social media accounts (e.g. https://twitter.com/POTUS), however, a consensus of credible reporting will also be used.",
	//    "outcomes":"[\\""Yes\\"", \\""No\\""]",
	//    "outcomePrices":"[\\"0\\", \\"1\\"]",
	//    "volume":"549414.493468",
	//    "active":true,
	//    "closed":true,
	//    "marketMakerAddress":"",
	//    "createdAt":"2025-09-19T19:32:28.841694Z",
	//    "updatedAt":"2026-03-09T22:44:28.896812Z",
	//    "closedTime":"2025-11-01 06:28:08+00",
	//    "new":false,
	//    "featured":false,
	//    "submitted_by":"0x91430CaD2d3975766499717fA0D66A78D814E5c5",
	//    "archived":false,
	//    "resolvedBy":"0x65070BE91477460D8A7AeEb94ef92fe056C2f2A7",
	//    "restricted":true,
	//    "groupItemTitle":"October 31, 2025",
	//    "groupItemThreshold":"0",
	//    "questionID":"0x2dd49c70f01a5e7c687a9820d606ff0d85fb50199735928d52d98b3a57586969",
	//    "umaEndDate":"2025-11-01T06:28:08Z",
	//    "enableOrderBook":true,
	//    "orderPriceMinTickSize":"0.001",
	//    "orderMinSize":"5",
	//    "umaResolutionStatus":"resolved",
	//    "volumeNum":"549414.493468",
	//    "endDateIso":"2025-10-31",
	//    "startDateIso":"2025-09-19",
	//    "hasReviewedDates":true,
	//    "volume1wk":"121949.66579699998",
	//    "volume1mo":"535231.3545640002",
	//    "volume1yr":"549414.4934680002",
	//    "clobTokenIds":"[\\"45601394554497090173642354630373884477724604907691447337031201817815960365378\\", \\"102652665954921241745169157447280060113772926009745753029489061659654862632571\\"]",
	//    "umaBond":"500",
	//    "umaReward":"5",
	//    "volume1wkClob":"121949.66579699998",
	//    "volume1moClob":"535231.3545640002",
	//    "volume1yrClob":"549414.4934680002",
	//    "volumeClob":"549414.493468",
	//    "customLiveness":"0",
	//    "acceptingOrders":false,
	//    "negRisk":false,
	//    "negRiskRequestID":"",
	//    "ready":false,
	//    "funded":false,
	//    "acceptingOrdersTimestamp":"2025-09-19T21:22:32Z",
	//    "cyom":false,
	//    "pagerDutyNotificationEnabled":false,
	//    "approved":true,
	//    "rewardsMinSize":"100",
	//    "rewardsMaxSpread":"3.5",
	//    "spread":"0.001",
	//    "automaticallyResolved":true,
	//    "oneDayPriceChange":"-0.0005",
	//    "oneWeekPriceChange":"-0.007",
	//    "oneMonthPriceChange":"-0.011",
	//    "lastTradePrice":"1",
	//    "bestAsk":"0.001",
	//    "automaticallyActive":true,
	//    "clearBookOnStart":true,
	//    "seriesColor":"",
	//    "showGmpSeries":false,
	//    "showGmpOutcome":false,
	//    "manualActivation":false,
	//    "negRiskOther":false,
	//    "umaResolutionStatuses":"[\\""proposed\\""]",
	//    "pendingDeployment":false,
	//    "deploying":false,
	//    "deployingTimestamp":"2025-09-19T21:22:01.979023Z",
	//    "rfqEnabled":false,
	//    "holdingRewardsEnabled":false,
	//    "feesEnabled":false,
	//    "requiresTranslation":false,
	//    "feeType":null
	// }
	//
	for mi := 0; mi < len(rawMarkets); mi++ {
		var market any = rawMarkets[mi]
		var conditionId *string = this.SafeString(market, "conditionId")
		var marketId *string = this.SafeString(market, "id")
		var marketSlug *string = this.SafeString(market, "slug", conditionId)
		var active *bool = this.SafeBool(market, "active", false)
		var closed *bool = this.SafeBool(market, "closed", false)
		// resolution: a closed/uma-resolved market settles each outcome price to 0 or 1
		var marketResolved bool = (closed != nil && *closed) || (this.SafeStringLower(market, "umaResolutionStatus") != nil && *this.SafeStringLower(market, "umaResolutionStatus") == "resolved")
		var resolvedOutcome any = nil
		// gamma exposes the order-book tick as orderPriceMinTickSize; minimumTickSize is the clob alias
		var tickSize *float64 = this.SafeNumber2(market, "orderPriceMinTickSize", "minimumTickSize", 0.01)
		// real per-market min order size (shares) and price tick — don't hardcode 1 / 0.01..0.99
		var orderMinSize *float64 = this.SafeNumber(market, "orderMinSize", 1)
		var priceMax *float64 = this.ParseNumber(ccxt.Precise.StringSub("1", this.NumberToString(tickSize)))
		var negRisk *bool = this.SafeBool(market, "negRisk", false)
		var endDate *string = this.SafeString(market, "endDate", this.SafeString(market, "end_date_iso"))
		// Gamma API returns these arrays as JSON-encoded strings
		var outcomeLabels any = []any{}
		var clobTokenIds any = []any{}
		var outcomePrices any = []any{}
		var parsedOutcomes any = this.ParseJson(this.SafeString(market, "outcomes", "[]"))
		var parsedTokenIds any = this.ParseJson(this.SafeString(market, "clobTokenIds", "[]"))
		var parsedPrices any = this.ParseJson(this.SafeString(market, "outcomePrices", "[]"))
		var parsedOutcomesLength any = nil
		if parsedOutcomes != nil {
			parsedOutcomesLength = ccxt.GetArrayLength(parsedOutcomes)
		}
		var parsedTokenIdsLength any = nil
		if parsedTokenIds != nil {
			parsedTokenIdsLength = ccxt.GetArrayLength(parsedTokenIds)
		}
		var parsedPricesLength any = nil
		if parsedPrices != nil {
			parsedPricesLength = ccxt.GetArrayLength(parsedPrices)
		}
		if (parsedOutcomes != nil) && (parsedOutcomesLength != nil) {
			outcomeLabels = parsedOutcomes
		}
		if (parsedTokenIds != nil) && (parsedTokenIdsLength != nil) {
			clobTokenIds = parsedTokenIds
		}
		if (parsedPrices != nil) && (parsedPricesLength != nil) {
			outcomePrices = parsedPrices
		}
		var outcomeLabelsLength int = ccxt.GetArrayLength(outcomeLabels)
		var clobTokenIdsLength int = ccxt.GetArrayLength(clobTokenIds)
		if (outcomeLabelsLength == 0) || (clobTokenIdsLength == 0) {
			continue
		}
		// ccxt.Market outcome (no outcome suffix)
		var marketSymbol any = this.SlugToMarketSymbol(eventSlug, marketSlug)
		// Build outcomes array
		var outcomes []any = []any{}
		for oi := 0; oi < ccxt.GetArrayLength(outcomeLabels); oi++ {
			var outcomeLabel any = ccxt.GetValue(outcomeLabels, oi)
			var clobTokenId any = ccxt.GetValue(clobTokenIds, oi)
			var outcomePrice *float64 = this.SafeNumber(outcomePrices, oi)
			if (clobTokenId == nil) || (clobTokenId == "") {
				continue
			}
			var outcomeHandle any = this.SlugToOutcomeSymbol(eventSlug, marketSlug, outcomeLabel)
			var winnerRaw any = nil
			var settleFractionRaw any = nil
			if marketResolved && (outcomePrice != nil) {
				// a genuinely-settled polymarket outcome is at 1 (won) or 0 (lost). a market
				// that is only closed-for-trading (not yet UMA-resolved) still has fractional
				// prices — don't report a fractional mid as a final settleFraction; leave the
				// outcome-level fields undefined until a decisive price exists
				if *outcomePrice >= 0.99 {
					winnerRaw = true
					settleFractionRaw = 1
					resolvedOutcome = outcomeHandle
				} else if 0.01 >= *outcomePrice {
					winnerRaw = false
					settleFractionRaw = 0
				}
			}
			// effectively-final copies: Java emits the object literal below as an anonymous
			// inner class, which cannot capture a reassigned local
			var winner any = winnerRaw
			var settleFraction any = settleFractionRaw
			outcomes = append(outcomes, map[string]any{
				"outcome":        outcomeHandle,
				"outcomeId":      clobTokenId,
				"market":         marketSymbol,
				"label":          outcomeLabel,
				"price":          outcomePrice,
				"active":         (active != nil && *active) && (!(closed != nil && *closed)),
				"winner":         winner,
				"settleFraction": settleFraction,
				"precision": map[string]any{
					"amount": tickSize,
					"price":  tickSize,
				},
				"negRisk": negRisk,
				"info":    market,
			})
		}
		var baseId *string = func() *string {
			if conditionId != nil {
				return conditionId
			}
			return marketId
		}()
		var marketType string = func() string {
			if outcomeLabelsLength > 2 {
				return "categorical"
			}
			return "binary"
		}()
		// effectively-final copy for the market object literal below (reassigned in the loop)
		var marketResolvedOutcome any = resolvedOutcome
		result = append(result, map[string]any{
			"id":              conditionId,
			"market":          marketSymbol,
			"marketType":      marketType,
			"executionModel":  "clob",
			"collateral":      "USDC",
			"base":            "USDC",
			"quote":           "USDC",
			"settle":          nil,
			"baseId":          baseId,
			"quoteId":         "USDC",
			"settleId":        nil,
			"type":            "prediction",
			"spot":            false,
			"margin":          false,
			"swap":            false,
			"future":          false,
			"option":          false,
			"prediction":      true,
			"active":          (active != nil && *active) && (!(closed != nil && *closed)),
			"resolved":        marketResolved,
			"resolvedOutcome": marketResolvedOutcome,
			"contract":        false,
			"linear":          nil,
			"inverse":         nil,
			"contractSize":    nil,
			"expiry": func() any {
				if (endDate != nil) && (endDate == nil || *endDate != "") {
					return this.Parse8601(endDate)
				}
				return nil
			}(),
			"expiryDatetime": endDate,
			"strike":         nil,
			"optionType":     nil,
			"taker":          0,
			"maker":          0,
			"percentage":     true,
			"tierBased":      false,
			"feeSide":        "get",
			"precision": map[string]any{
				"amount": tickSize,
				"price":  tickSize,
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": 1,
					"max": 1,
				},
				"amount": map[string]any{
					"min": orderMinSize,
					"max": nil,
				},
				"price": map[string]any{
					"min": tickSize,
					"max": priceMax,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"outcomes": outcomes,
			"info":     market,
			"created":  nil,
		})
	}
	return result
}

/**
 * @ignore
 * @method
 * @name polymarket#fetchOutcome
 * @description resolves a single outcome by its CLOB token id in one request, so a cache miss
 * (a bare token id, or a valid outcome on a market outside the top-volume cold cache) recovers
 * instead of throwing ccxt.BadSymbol. an outcome HANDLE ("MARKET:LABEL") carries no token id, so it
 * falls back to the base bulk load
 * @param {string} outcomeSymbol the outcome token id or handle
 * @returns {object} the resolved outcome object
 */
func (this *Polymarket) FetchOutcomeAsync(outcomeSymbol any) <-chan ccxt.AsyncResult[ccxt.PredictionOutcome] {
	ch := make(chan ccxt.AsyncResult[ccxt.PredictionOutcome], 1)
	go this.fetchOutcomeBody(ch, outcomeSymbol)
	return ch
}
func (this *Polymarket) fetchOutcomeBody(ch chan ccxt.AsyncResult[ccxt.PredictionOutcome], outcomeSymbol any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// a bare CLOB token id has no ':' (an outcome handle is always "MARKET:LABEL") and no
	// searchable words — outcomeSearchQuery returns undefined only for id-like inputs, so
	// word-bearing junk like 'BTC/USDT' skips the gamma by-id lookup (which 422s on
	// non-ids) and falls through to the search path and its local ccxt.BadSymbol below.
	// absence must be `< 0` — the php transpiler maps that to `=== false`, while a literal
	// `=== -1` passes through and never matches mb_strpos's false return
	if (ccxt.GetIndexOf(outcomeSymbol, ":") < 0) && (ccxt.IsEqual(this.OutcomeSearchQuery(outcomeSymbol), nil)) {

		r := <-this.GammaPublicGetMarkets(map[string]any{
			"clob_token_ids": outcomeSymbol,
		})
		if r.Err != nil {
			panic(r.Err)
		}
		response := r.Raw
		var rawMarkets any = func() any {
			if !ccxt.IsEqual(response, nil) {
				return response
			}
			return []any{}
		}()
		var rawMarketsLength int = ccxt.GetArrayLength(rawMarkets)
		if rawMarketsLength > 0 {
			if this.Markets() == nil {
				this.PublishMarkets(map[string]any{})
			}
			var ccxtMarkets []any = ccxt.ArrayTyped(this.ParseEventToMarkets(map[string]any{
				"markets": rawMarkets,
			}))
			var ccxtMarketsLength int = len(ccxtMarkets)
			for i := 0; i < ccxtMarketsLength; i++ {
				var mkt any = ccxt.DerefScalar(ccxtMarkets[i])
				if ccxt.IsEqual(mkt, nil) {
					panic(ccxt.ExchangeError(this.Id + " fetchOutcome() could not resolve mkt"))
				}
				this.AddMarketsEntry(ccxt.GetValue(mkt, "market"), mkt)
			}
			this.PopulateOutcomes()
			if !ccxt.IsEqual(this.SafeDict(this.Outcomes_by_id, outcomeSymbol), nil) {

				ch <- ccxt.AsyncResult[ccxt.PredictionOutcome]{Value: ccxt.PredictionOutcomeFromMap(this.SafeDictMap(this.Outcomes_by_id, outcomeSymbol))}
				return nil
			}
		}
	}

	r1 := <-this.BaseExchange.FetchOutcomeAsync(outcomeSymbol)
	if r1.Err != nil {
		panic(r1.Err)
	}
	ch <- ccxt.AsyncResult[ccxt.PredictionOutcome]{Value: r1.Value}
	return nil
}

/**
 * @ignore
 * @method
 * @name polymarket#fetchOutcomes
 * @description resolves several uncached outcomes at once — bare CLOB token ids are batched into gamma markets requests (repeated clob_token_ids params, 50 per request to keep the URL bounded); handle-shaped symbols fall back to the single fetch and its search path
 * @see https://docs.polymarket.com/api-reference/markets/list-markets
 * @param {string[]} outcomeSymbols outcome token ids or handles
 * @returns {object} the outcome cache
 */
func (this *Polymarket) FetchOutcomesAsync(outcomeSymbols any) <-chan ccxt.AsyncResult[map[string]ccxt.PredictionOutcome] {
	ch := make(chan ccxt.AsyncResult[map[string]ccxt.PredictionOutcome], 1)
	go this.fetchOutcomesBody(ch, outcomeSymbols)
	return ch
}
func (this *Polymarket) fetchOutcomesBody(ch chan ccxt.AsyncResult[map[string]ccxt.PredictionOutcome], outcomeSymbols any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var tokenIds []any = []any{}
	for i := 0; i < ccxt.GetArrayLength(outcomeSymbols); i++ {
		var outcomeSymbol *string = ccxt.SafeStringPtr(ccxt.GetValue(outcomeSymbols, i))
		// only id-like symbols (no ':', no searchable words) belong in the by-id batch —
		// see the same gate in fetchOutcome. absence must be `< 0` — the php transpiler
		// maps that to `=== false`, while a literal `=== -1` passes through and never
		// matches mb_strpos's false return
		if (strings.Index(*outcomeSymbol, ":") < 0) && (ccxt.IsEqual(this.OutcomeSearchQuery(outcomeSymbol), nil)) {
			tokenIds = append(tokenIds, outcomeSymbol)
		}
	}
	var tokenIdsLength int = len(tokenIds)
	if tokenIdsLength > 0 {
		if this.Markets() == nil {
			this.PublishMarkets(map[string]any{})
		}
		// token ids are ~78 chars each, so cap the batch to keep the URL under common limits
		var chunkSize *int64 = this.SafeInteger(this.Options, "fetchOutcomesBatchSize", 50)
		var startIndex any = 0
		for ccxt.IsLessThan(startIndex, tokenIdsLength) {
			var endIndex any = this.Sum(startIndex, chunkSize)
			if ccxt.IsGreaterThan(endIndex, tokenIdsLength) {
				endIndex = tokenIdsLength
			}
			var chunk []any = []any{}
			for i := int(ccxt.ParseInt(startIndex)); ccxt.IsLessThan(i, endIndex); i++ {
				chunk = append(chunk, ccxt.GetValue(tokenIds, i))
			}
			// gamma matches repeated clob_token_ids params — comma-joined ids are rejected
			// with a validation error, so the list rides through urlencodeWithArrayRepeat

			r := <-this.GammaPublicGetMarkets(map[string]any{
				"clob_token_ids": chunk,
				"limit":          chunkSize,
			})
			if r.Err != nil {
				panic(r.Err)
			}
			response := r.Raw
			var rawMarkets any = func() any {
				if !ccxt.IsEqual(response, nil) {
					return response
				}
				return []any{}
			}()
			var ccxtMarkets []any = ccxt.ArrayTyped(this.ParseEventToMarkets(map[string]any{
				"markets": rawMarkets,
			}))
			for i := 0; i < len(ccxtMarkets); i++ {
				var mkt any = ccxtMarkets[i]
				if ccxt.IsEqual(mkt, nil) {
					panic(ccxt.ExchangeError(this.Id + " fetchOutcomes() could not resolve mkt"))
				}
				this.AddMarketsEntry(ccxt.GetValue(mkt, "market"), mkt)
			}
			startIndex = this.Sum(startIndex, chunkSize)
		}
		this.PopulateOutcomes()
	}
	for i := 0; i < ccxt.GetArrayLength(outcomeSymbols); i++ {
		if !this.HasOutcome(ccxt.GetValue(outcomeSymbols, i)) {

			r1 := <-this.FetchOutcomeAsync(ccxt.GetValue(outcomeSymbols, i))
			if r1.Err != nil {
				panic(r1.Err)
			}
		}
	}

	ch <- ccxt.AsyncResult[map[string]ccxt.PredictionOutcome]{Value: ccxt.PredictionOutcomeMapFromMap(this.Outcomes)}
	return nil
}

/**
 * @method
 * @name polymarket#fetchTicker
 * @description fetches the current mid-price and best bid/ask for a single outcome token
 * @see https://docs.polymarket.com/api-reference/data/get-midpoint-price
 * @see https://docs.polymarket.com/api-reference/market-data/get-order-book
 * @see https://docs.polymarket.com/api-reference/data/get-last-trade-price
 * @param {string} outcome unified outcome like TRUMP_DANCE_TODAY_997:YES or an outcome token id
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
 */
func (this *Polymarket) FetchTickerAsync(outcome string, optionalArgs ...any) <-chan ccxt.AsyncResult[ccxt.PredictionTicker] {
	ch := make(chan ccxt.AsyncResult[ccxt.PredictionTicker], 1)
	go this.fetchTickerBody(ch, outcome, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchTickerBody(ch chan ccxt.AsyncResult[ccxt.PredictionTicker], outcome string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadOutcomeAsync(outcome)
	if r.Err != nil {
		panic(r.Err)
	}
	var outcomeObj any = nil
	if !ccxt.StructAbsent(r.Value) {
		outcomeObj = ccxt.StructBox(r.Value, ccxt.PredictionOutcomeToMap)
	}
	var tokenId *string = this.SafeString(outcomeObj, "outcomeId")
	var promises []any = []any{this.ClobPublicGetMidpoint(map[string]any{
		"token_id": tokenId,
	}), this.ClobPublicGetBook(map[string]any{
		"token_id": tokenId,
	}), this.ClobPublicGetLastTradePrice(map[string]any{
		"token_id": tokenId,
	})}
	r1 := <-ccxt.PromiseAll(promises)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var midpointResponsebookResponselastTradeResponseVariable []any = ccxt.ListTyped(r1.Value)
	midpointResponse := midpointResponsebookResponselastTradeResponseVariable[0]
	bookResponse := midpointResponsebookResponselastTradeResponseVariable[1]
	lastTradeResponse := midpointResponsebookResponselastTradeResponseVariable[2]
	var response map[string]any = map[string]any{
		"midpoint":  midpointResponse,
		"book":      bookResponse,
		"lastTrade": lastTradeResponse,
	}

	//
	//     {
	//         "midpoint": {
	//             "mid": "0.9985"
	//         },
	//         "book": {
	//             "market": "0x2d55f622bc12e23dc1f1bb4db8360c28c92155f9376bf73953c0756ee1387b2f",
	//             "asset_id": "16718041887881762329859205887704087070587186248220606272297433440108449709696",
	//             "timestamp": "1777344471023",
	//             "hash": "11aa0feabec970de83b04a2c0d50a7639e144f43",
	//             "bids": [
	//                 {
	//                     "price": "0.46",
	//                     "size": "100"
	//                 },
	//             ],
	//             "asks": [
	//                 {
	//                     "price": "0.46",
	//                     "size": "150"
	//                 },
	//             ],
	//             "min_order_size": "5",
	//             "tick_size": "0.001",
	//             "neg_risk": false,
	//             "last_trade_price": "0.998"
	//         },
	//         "lastTrade": {
	//             "price": "0.46",
	//             "side": "BUY"
	//         }
	//     }
	//
	ch <- ccxt.AsyncResult[ccxt.PredictionTicker]{Value: ccxt.PredictionTickerFromMap(this.ParsePredictionTicker(response, outcomeObj))}
	return nil
}

/**
 * @method
 * @name polymarket#fetchTickers
 * @description fetches tickers for multiple outcome tokens at once using the batched CLOB book, midpoint and last-trade-price endpoints (200 per request trio)
 * @see https://docs.polymarket.com/api-reference/market-data/get-order-books-request-body
 * @see https://docs.polymarket.com/api-reference/market-data/get-midpoint-prices-request-body
 * @see https://docs.polymarket.com/api-reference/data/get-last-trades-prices
 * @param {string[]} outcomes unified outcomes or outcome token ids — required: polymarket has no endpoint returning all tickers at once, so an unscoped call is not supported
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [prediction ticker structures](https://docs.ccxt.com/#/?id=prediction-ticker-structure) indexed by outcome
 */
func (this *Polymarket) FetchTickersAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[map[string]ccxt.PredictionTicker] {
	ch := make(chan ccxt.AsyncResult[map[string]ccxt.PredictionTicker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchTickersBody(ch chan ccxt.AsyncResult[map[string]ccxt.PredictionTicker], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var outcomes []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = outcomes
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if outcomes == nil {
		panic(ccxt.ArgumentsRequired(this.Id + " fetchTickers() requires an outcomes argument — the venue has no all-tickers endpoint; pass the outcome handles or token ids to fetch (discover them via fetchEvents ())"))
	}
	// batch-resolve the uncached outcomes (one gamma request per 50 token ids)

	r := <-this.LoadOutcomesAsync(outcomes)
	if r.Err != nil {
		panic(r.Err)
	}
	var targets []any = []any{}
	for oi := 0; oi < len(outcomes); oi++ {
		targets = append(targets, outcomes[oi])
	}
	var outcomesByTokenId map[string]any = map[string]any{}
	var tokenIds []any = []any{}
	for i := 0; i < len(targets); i++ {
		var outcomeObj map[string]any = this.Outcome(ccxt.DerefScalar(targets[i]))
		var tokenId *string = this.SafeString(outcomeObj, "outcomeId")
		if tokenId != nil {
			if _, ok := outcomesByTokenId[*tokenId]; !ok {
				ccxt.AddElementToObject(outcomesByTokenId, tokenId, outcomeObj)
				tokenIds = append(tokenIds, tokenId)
			}
		}
	}
	var chunkSize *int64 = this.SafeInteger(this.Options, "fetchTickersBatchSize", 200)
	var result map[string]any = map[string]any{}
	var tokenIdsLength int = len(tokenIds)
	var startIndex any = 0
	for ccxt.IsLessThan(startIndex, tokenIdsLength) {
		var endIndex any = this.Sum(startIndex, chunkSize)
		if ccxt.IsGreaterThan(endIndex, tokenIdsLength) {
			endIndex = tokenIdsLength
		}
		var bookParams []any = []any{}
		for i := int(ccxt.ParseInt(startIndex)); ccxt.IsLessThan(i, endIndex); i++ {
			bookParams = append(bookParams, map[string]any{
				"token_id": ccxt.GetValue(tokenIds, i),
			})
		}
		var promises []any = []any{this.ClobPublicPostBooks(bookParams), this.ClobPublicPostMidpoints(bookParams), this.ClobPublicPostLastTradesPrices(bookParams)}

		r1 := <-ccxt.PromiseAll(promises)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var responses []any = ccxt.ListTyped(r1.Value)
		var booksResponse any = responses[0]
		var midpoints any = responses[1]
		var lastTradesResponse any = responses[2]
		var booksIsArray bool = ccxt.IsArray(booksResponse)
		var books any = func() any {
			if booksIsArray {
				return booksResponse
			}
			return []any{}
		}()
		var lastTradesIsArray bool = ccxt.IsArray(lastTradesResponse)
		var lastTrades any = func() any {
			if lastTradesIsArray {
				return lastTradesResponse
			}
			return []any{}
		}()
		var lastTradesByTokenId map[string]any = map[string]any{}
		var lastTradesLength int = ccxt.GetArrayLength(lastTrades)
		for li := 0; li < lastTradesLength; li++ {
			var lastTradeEntry any = ccxt.GetValue(lastTrades, li)
			var lastTradeTokenId *string = this.SafeString(lastTradeEntry, "token_id")
			if lastTradeTokenId != nil {
				lastTradesByTokenId[*lastTradeTokenId] = lastTradeEntry
			}
		}
		var booksLength int = ccxt.GetArrayLength(books)
		for i := 0; i < booksLength; i++ {
			var book any = ccxt.GetValue(books, i)
			var tokenId *string = this.SafeString(book, "asset_id")
			if (tokenId == nil) || !(func() bool {
				if tokenId == nil {
					return false
				}
				_, ok := outcomesByTokenId[*tokenId]
				return ok
			}()) {
				continue
			}
			var outcomeObj any = func() any {
				if tokenId == nil {
					return nil
				}
				return outcomesByTokenId[*tokenId]
			}()
			var mid *string = this.SafeString(midpoints, tokenId)
			var tickerInput map[string]any = map[string]any{
				"midpoint": map[string]any{
					"mid": mid,
				},
				"book":      book,
				"lastTrade": this.SafeDict(lastTradesByTokenId, tokenId, map[string]any{}),
			}
			var ticker map[string]any = this.ParsePredictionTicker(tickerInput, outcomeObj)
			var symbolKey *string = this.SafeString(ticker, "outcome", tokenId)
			if symbolKey != nil {
				result[*symbolKey] = ticker
			}
		}
		startIndex = this.Sum(startIndex, chunkSize)
	}

	ch <- ccxt.AsyncResult[map[string]ccxt.PredictionTicker]{Value: ccxt.PredictionTickerMapFromMap(result)}
	return nil
}

/**
 * @ignore
 * @method
 * @name polymarket#parsePredictionTicker
 * @description parses a combined midpoint + order book response into a unified ticker object
 * @param {object} ticker a dict with midpoint and book entries
 * @param {object} [market] the outcome object the ticker belongs to
 * @returns {object} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
 */
func (this *Polymarket) ParsePredictionTicker(ticker any, optionalArgs ...any) map[string]any {
	//
	//     {
	//         "midpoint": {
	//             "mid": "0.9985"
	//         },
	//         "book": {
	//             "market": "0x2d55f622bc12e23dc1f1bb4db8360c28c92155f9376bf73953c0756ee1387b2f",
	//             "asset_id": "16718041887881762329859205887704087070587186248220606272297433440108449709696",
	//             "timestamp": "1777344471023",
	//             "hash": "11aa0feabec970de83b04a2c0d50a7639e144f43",
	//             "bids": [
	//                 {
	//                     "price": "0.45",
	//                     "size": "100"
	//                 },
	//             ],
	//             "asks": [
	//                 {
	//                     "price": "0.46",
	//                     "size": "150"
	//                 },
	//             ],
	//             "min_order_size": "5",
	//             "tick_size": "0.001",
	//             "neg_risk": false,
	//             "last_trade_price": "0.998"
	//         },
	//         "lastTrade": {
	//             "price": "0.46",
	//             "side": "BUY"
	//         }
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var midpointData map[string]any = ccxt.SafeMapTyped(ticker, "midpoint")
	var bookData map[string]any = ccxt.SafeMapTyped(ticker, "book")
	var mid *float64 = this.SafeNumber(midpointData, "mid")
	var bids []any = ccxt.SafeListTyped(bookData, "bids")
	var asks []any = ccxt.SafeListTyped(bookData, "asks")
	var bidsLength int = len(bids)
	var asksLength int = len(asks)
	// the CLOB book endpoint returns levels sorted away from the touch (bids ascending, asks descending), so the best level is the last entry
	var bestBid any = func() any {
		if bidsLength > 0 {
			return func() any {
				if bidsLength-1 >= 0 && bidsLength-1 < len(bids) {
					return bids[bidsLength-1]
				}
				return nil
			}()
		}
		return nil
	}()
	var bestAsk any = func() any {
		if asksLength > 0 {
			return func() any {
				if asksLength-1 >= 0 && asksLength-1 < len(asks) {
					return asks[asksLength-1]
				}
				return nil
			}()
		}
		return nil
	}()
	// book.last_trade_price is market-level and denominated in whichever token traded last —
	// on the complementary token it is the OTHER side's price, so only the per-token
	// last-trade-price endpoint value is usable here; that endpoint reports "0" for a
	// never-traded token, which also falls back to the mid
	var lastTradeData map[string]any = ccxt.SafeMapTyped(ticker, "lastTrade")
	var last *float64 = this.SafeNumber(lastTradeData, "price")
	if (last == nil) || (last != nil && *last == 0) {
		last = mid
	}
	var outcome any = this.SafeOutcomeSymbol(nil, market)
	var timestamp *int64 = this.SafeInteger(bookData, "timestamp")
	var quoteVolume *float64 = nil
	if market != nil {
		quoteVolume = this.SafeNumber2(market["info"], "volume24hr", "volume")
	}
	return this.SafePredictionTicker(map[string]any{
		"outcome":       outcome,
		"outcomeId":     this.SafeString(market, "outcomeId"),
		"label":         this.SafeString(market, "label"),
		"market":        this.SafeString(market, "market"),
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          nil,
		"low":           nil,
		"bid":           this.SafeNumber(bestBid, "price"),
		"bidVolume":     this.SafeNumber(bestBid, "size"),
		"ask":           this.SafeNumber(bestAsk, "price"),
		"askVolume":     this.SafeNumber(bestAsk, "size"),
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       mid,
		"baseVolume":    nil,
		"quoteVolume":   quoteVolume,
		"info":          ticker,
	}, market)
}

/**
 * @method
 * @name polymarket#fetchOrderBook
 * @description fetches the CLOB order book for a single outcome token
 * @see https://docs.polymarket.com/api-reference/market-data/get-order-book
 * @param {string} outcome unified outcome or outcome token id
 * @param {int} [limit] not used by polymarket fetchOrderBook
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
 */
func (this *Polymarket) FetchOrderBookAsync(outcome string, optionalArgs ...any) <-chan ccxt.AsyncResult[ccxt.PredictionOrderBook] {
	ch := make(chan ccxt.AsyncResult[ccxt.PredictionOrderBook], 1)
	go this.fetchOrderBookBody(ch, outcome, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchOrderBookBody(ch chan ccxt.AsyncResult[ccxt.PredictionOrderBook], outcome string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	r := <-this.LoadOutcomeAsync(outcome)
	if r.Err != nil {
		panic(r.Err)
	}
	var outcomeObj any = nil
	if !ccxt.StructAbsent(r.Value) {
		outcomeObj = ccxt.StructBox(r.Value, ccxt.PredictionOutcomeToMap)
	}
	var tokenId *string = this.SafeString(outcomeObj, "outcomeId")
	var request map[string]any = map[string]any{
		"token_id": tokenId,
	}

	r1 := <-this.ClobPublicGetBook(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "market": "0x42d42b30124ed2d93800358dfd1d48253114e4d58cff15cb765cd0c69956555f",
	//         "asset_id": "53471586309106256293075593293890793127405137223521910882276033765569397092350",
	//         "timestamp": "1777541385018",
	//         "hash": "bfb61f58dab4055d956eb5e758dbc9101c9a4e6c",
	//         "bids": [
	//             { "price": "0.001", "size": "3147.19" },
	//             { "price": "0.002", "size": "1432.11" }
	//         ],
	//         "asks": [
	//             { "price": "0.999", "size": "73.68" },
	//             { "price": "0.998", "size": "7" }
	//         ],
	//         "min_order_size": "5",
	//         "tick_size": "0.001",
	//         "neg_risk": false,
	//         "last_trade_price": "0.002"
	//     }
	//
	var timestamp *int64 = this.SafeInteger(response, "timestamp")
	var orderbook map[string]any = this.ParseOrderBook(response, this.SafeOutcomeSymbol(outcome, outcomeObj), timestamp, "bids", "asks", "price", "size")

	ch <- ccxt.AsyncResult[ccxt.PredictionOrderBook]{Value: ccxt.PredictionOrderBookFromMap(this.SafePredictionOrderBook(orderbook, outcomeObj))}
	return nil
}

/**
 * @method
 * @name polymarket#fetchOHLCV
 * @description fetches price history ticks for a single outcome token and buckets them client-side into ccxt.OHLCV candles, snapping tick timestamps to the candle boundary
 * @see https://docs.polymarket.com/api-reference/markets/get-prices-history
 * @param {string} outcome unified outcome or outcome token id
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum number of candles to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int[][]} a list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Polymarket) FetchOHLCVAsync(outcome string, optionalArgs ...any) <-chan ccxt.AsyncResult[[]ccxt.OHLCV] {
	ch := make(chan ccxt.AsyncResult[[]ccxt.OHLCV], 1)
	go this.fetchOHLCVBody(ch, outcome, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchOHLCVBody(ch chan ccxt.AsyncResult[[]ccxt.OHLCV], outcome string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// hoisted keys list: chaining join onto Object.keys breaks the python transpiler
	var timeframe string = ccxt.GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if !(ccxt.InOp(this.Timeframes, timeframe)) {
		var supportedKeys []string = ccxt.ObjectKeys(this.Timeframes)
		panic(ccxt.BadRequest(this.Id + " fetchOHLCV() unsupported timeframe " + timeframe + ", supported timeframes are " + strings.Join(supportedKeys, ", ")))
	}

	r := <-this.LoadOutcomeAsync(outcome)
	if r.Err != nil {
		panic(r.Err)
	}
	var outcomeObj map[string]any = ccxt.StructResultMap(r.Value, ccxt.PredictionOutcomeToMap)
	var tokenId *string = this.SafeString(outcomeObj, "outcomeId")
	var fidelityMin *int64 = this.SafeInteger(this.Timeframes, timeframe, 1) // fidelity in minutes
	var nowS int64 = this.Seconds()
	var startS any = nil
	var endS any = nowS
	if since != nil {
		startS = this.ParseToInt(float64(*since) / 1000)
		if limit != nil {
			var endBound any = this.Sum(startS, ccxt.Multiply(ccxt.Multiply(limit, fidelityMin), 60))
			endS = func() any {
				if ccxt.IsLessThan(endBound, nowS) {
					return endBound
				}
				return nowS
			}()
		}
	} else {
		var barCount any = func() any {
			if limit != nil {
				return limit
			}
			return 100
		}()
		startS = ccxt.Subtract(nowS, (ccxt.Multiply(ccxt.Multiply(barCount, fidelityMin), 60)))
	}
	// the venue rejects startTs/endTs spans over 15 days ("interval is too long")
	// regardless of fidelity, so clamp the window to the cap: keep the requested
	// `since` anchor (oldest chunk first, consistent with since/limit paging),
	// or the most recent window when no `since` was given
	var maxWindow *int64 = this.SafeInteger(this.Options, "maxPricesHistoryWindow", 1296000)
	if ccxt.IsGreaterThan((ccxt.Subtract(endS, startS)), maxWindow) {
		if since != nil {
			endS = this.Sum(startS, maxWindow)
		} else {
			startS = ccxt.Subtract(endS, maxWindow)
		}
	}
	var request map[string]any = map[string]any{
		"market":   tokenId,
		"fidelity": fidelityMin,
		"startTs":  startS,
		"endTs":    endS,
	}

	r1 := <-this.ClobPublicGetPricesHistory(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "history": [
	//             { "t": "1776043119", "p": "0.265" },
	//         ]
	//     }
	//
	var history []any = ccxt.SafeListTyped(response, "history")
	// ccxt.Client-side bucket aggregation: snap each tick to its candle boundary and
	// build open/high/low/close/volume. Assumes history is sorted ascending by time.
	var resolutionMs int64 = (*fidelityMin * 60) * 1000
	var buckets map[string]any = map[string]any{}
	for i := 0; i < len(history); i++ {
		var item map[string]any = ccxt.SafeMapTyped(history, i)
		var t *int64 = this.SafeInteger(item, "t")
		var price *float64 = this.SafeNumber(item, "p")
		if (t == nil) || (price == nil) {
			continue
		}
		var rawMs int64 = *t * 1000
		var snappedMs int64 = this.ParseToInt(ccxt.Divide(rawMs, resolutionMs)) * resolutionMs
		// the venue supplies no candle volume ({t, p} ticks only) — leave it undefined
		// rather than fabricating a 0, probing s/v in case the field ever appears
		var vol *float64 = this.SafeNumber(item, "s")
		if vol == nil {
			vol = this.SafeNumber(item, "v")
		}
		var bucketKey string = strconv.FormatInt(snappedMs, 10)
		if _, ok := buckets[bucketKey]; !ok {
			buckets[bucketKey] = []any{snappedMs, price, price, price, price, vol}
		} else {
			var candle any = this.SafeList(buckets, bucketKey, []any{})
			ccxt.AddElementToObject(candle, 2, ccxt.MathMax(ccxt.GetValue(candle, 2), price)) // high
			ccxt.AddElementToObject(candle, 3, ccxt.MathMin(ccxt.GetValue(candle, 3), price)) // low
			ccxt.AddElementToObject(candle, 4, price)                                         // close (last tick wins)
			if vol != nil {
				var prevVol any = ccxt.GetValue(candle, 5)
				ccxt.AddElementToObject(candle, 5, func() any {
					if prevVol == nil {
						return vol
					}
					return this.Sum(prevVol, vol)
				}()) // volume
			}
			buckets[bucketKey] = candle // reassign after mutation, php arrays are value types
		}
	}
	var bucketKeys []string = nil
	if buckets != nil {
		bucketKeys = make([]string, 0, len(buckets))
		for objectKey := range buckets {
			bucketKeys = append(bucketKeys, objectKey)
		}
	}
	var unsortedCandles []any = []any{}
	for i := 0; i < len(bucketKeys); i++ {
		unsortedCandles = append(unsortedCandles, ccxt.GetValue(buckets, bucketKeys[i]))
	}
	var candles []any = this.SortBy(unsortedCandles, 0)
	var candlesLength int = len(candles)
	if (limit != nil) && (ccxt.IsGreaterThan(candlesLength, limit)) {

		ch <- ccxt.AsyncResult[[]ccxt.OHLCV]{Value: ccxt.OHLCVsFromList(this.ArraySlice(candles, ccxt.OpNeg(limit)))}
		return nil
	}

	ch <- ccxt.AsyncResult[[]ccxt.OHLCV]{Value: ccxt.OHLCVsFromList(candles)}
	return nil
}
func (this *Polymarket) ParseOHLCV(ohlcv any, optionalArgs ...any) ccxt.OHLCV {
	// Unused: fetchOHLCV performs client-side bucket aggregation directly.
	//
	//     {
	//         "t": "1776043119",
	//         "p": "0.265"
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var price *float64 = this.SafeNumber(ohlcv, "p")
	return ccxt.OHLCVFromList([]any{this.SafeTimestamp(ohlcv, "t"), price, price, price, price, nil})
}

