/**
 * @method
 * @name polymarket#watchTicker
 * @description streams a synthetic ticker derived from order-book snapshots and deltas (mid = (bid + ask) / 2)
 * @param {string} outcome unified outcome
 * @param {object} [params] extra params (unused)
 * @returns {object} a [prediction ticker structure]{@link https://docs.ccxt.com/#/?id=prediction-ticker-structure}
 */
func (this *Polymarket) WatchTickerAsync(outcome string, optionalArgs ...any) <-chan ccxt.AsyncResult[ccxt.PredictionTicker] {
	ch := make(chan ccxt.AsyncResult[ccxt.PredictionTicker], 1)
	go this.watchTickerBody(ch, outcome, optionalArgs...)
	return ch
}
func (this *Polymarket) watchTickerBody(ch chan ccxt.AsyncResult[ccxt.PredictionTicker], outcome string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadOutcomeAsync(outcome)
	if r.Err != nil {
		panic(r.Err)
	}
	var outcomeObj map[string]any = ccxt.StructResultMap(r.Value, ccxt.PredictionOutcomeToMap)
	var tokenId *string = this.SafeString(outcomeObj, "outcomeId", "")
	var outcomeValue *string = this.SafeString(outcomeObj, "outcome")
	if outcomeValue == nil {
		panic(ccxt.ExchangeError(this.Id + " watchTicker() missing outcome"))
	}
	var messageHash string = "ticker::" + *outcomeValue
	var subscribeHash string = "subscribe::" + *tokenId
	var subscribeMsg map[string]any = map[string]any{
		"assets_ids": []any{tokenId},
		"type":       "market",
	}
	if outcomeValue != nil {
		var seededBook any = this.OrderBook(map[string]any{})
		if !this.WsCacheHas("Orderbooks", *outcomeValue) {
			this.WsCacheSet("Orderbooks", *outcomeValue, seededBook)
		}
	}
	var url any = this.UrlsApi["ws"]

	r1 := <-this.Watch(url, messageHash, subscribeMsg, subscribeHash)
	if r1.Err != nil {
		panic(r1.Err)
	}
	orderbook := r1.Value
	var bids any = ccxt.GetValue(orderbook, "bids")
	var asks any = ccxt.GetValue(orderbook, "asks")
	var bestBid any = nil
	var bestBidVolume any = nil
	var bidsLength int = 0
	if bids != nil {
		bidsLength = ccxt.GetArrayLength(bids)
	}
	if (bids != nil) && (bidsLength > 0) {
		bestBid = ccxt.GetValue(ccxt.GetValue(bids, 0), 0)
		bestBidVolume = ccxt.GetValue(ccxt.GetValue(bids, 0), 1)
	}
	var bestAsk any = nil
	var bestAskVolume any = nil
	var asksLength int = 0
	if asks != nil {
		asksLength = ccxt.GetArrayLength(asks)
	}
	if (asks != nil) && (asksLength > 0) {
		bestAsk = ccxt.GetValue(ccxt.GetValue(asks, 0), 0)
		bestAskVolume = ccxt.GetValue(ccxt.GetValue(asks, 0), 1)
	}
	var mid any = nil
	if (!ccxt.IsEqual(bestBid, nil)) && (!ccxt.IsEqual(bestAsk, nil)) {
		var sum *string = ccxt.Precise.StringAdd(this.NumberToString(bestBid), this.NumberToString(bestAsk))
		mid = this.ParseNumber(ccxt.Precise.StringDiv(sum, "2"))
	} else if !ccxt.IsEqual(bestBid, nil) {
		mid = bestBid
	} else {
		mid = bestAsk
	}
	var market map[string]any = this.SafeOutcome(outcomeValue)

	ch <- ccxt.AsyncResult[ccxt.PredictionTicker]{Value: ccxt.PredictionTickerFromMap(this.SafePredictionTicker(map[string]any{
		"outcome":       outcomeValue,
		"outcomeId":     this.SafeString(market, "outcomeId"),
		"label":         this.SafeString(market, "label"),
		"market":        this.SafeString(market, "market"),
		"timestamp":     ccxt.GetValue(orderbook, "timestamp"),
		"datetime":      ccxt.GetValue(orderbook, "datetime"),
		"high":          nil,
		"low":           nil,
		"bid":           bestBid,
		"bidVolume":     bestBidVolume,
		"ask":           bestAsk,
		"askVolume":     bestAskVolume,
		"vwap":          nil,
		"open":          nil,
		"close":         mid,
		"last":          mid,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       mid,
		"baseVolume":    nil,
		"quoteVolume":   nil,
		"info":          orderbook,
	}, market))}
	return nil
}

/**
 * @method
 * @name polymarket#watchOrders
 * @description watches the authenticated user's order updates over the CLOB user websocket channel
 * @see https://docs.polymarket.com/developers/CLOB/websocket/user-channel
 * @param {string} [outcome] unified outcome to filter the stream to one market
 * @param {int} [since] the earliest time in ms to return orders for
 * @param {int} [limit] the maximum number of orders to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
 */
func (this *Polymarket) WatchOrdersAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[[]ccxt.PredictionOrder] {
	ch := make(chan ccxt.AsyncResult[[]ccxt.PredictionOrder], 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) watchOrdersBody(ch chan ccxt.AsyncResult[[]ccxt.PredictionOrder], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var outcome *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = outcome
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	r := <-this.LoadApiCredentialsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var messageHash string = "orders"
	var outcomeResolved *string = outcome
	if outcomeResolved != nil {

		r1 := <-this.LoadOutcomeAsync(outcomeResolved)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var outcomeObj map[string]any = ccxt.StructResultMap(r1.Value, ccxt.PredictionOutcomeToMap)
		outcomeResolved = this.SafeString(outcomeObj, "outcome")
		var outcomeName *string = this.SafeString(outcomeObj, "outcome", "")
		messageHash = "orders::" + *outcomeName
	}

	r2 := <-this.SubscribeUserChannelAsync(messageHash, params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(r2.Value)
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(orders).GetLimit(outcomeResolved, limitResolved)
	}

	ch <- ccxt.AsyncResult[[]ccxt.PredictionOrder]{Value: ccxt.PredictionOrdersFromList(this.FilterByOutcomeSinceLimit(orders, outcomeResolved, since, limitResolved, true))}
	return nil
}

